import re


class StackUnderflowError(Exception):
    pass


_NUMBER = re.compile(r"-?\d+")


def evaluate(input_data):
    stack = []
    words = {}

    def pop():
        if not stack:
            raise StackUnderflowError("Insufficient number of items in stack")
        return stack.pop()

    def execute(token):
        if token in words:
            for sub in words[token]:
                execute(sub)
            return
        if _NUMBER.fullmatch(token):
            stack.append(int(token))
            return
        if token == "+":
            b, a = pop(), pop()
            stack.append(a + b)
        elif token == "-":
            b, a = pop(), pop()
            stack.append(a - b)
        elif token == "*":
            b, a = pop(), pop()
            stack.append(a * b)
        elif token == "/":
            b, a = pop(), pop()
            if b == 0:
                raise ZeroDivisionError("divide by zero")
            q = abs(a) // abs(b)
            stack.append(q if (a < 0) == (b < 0) else -q)
        elif token == "dup":
            if not stack:
                raise StackUnderflowError("Insufficient number of items in stack")
            stack.append(stack[-1])
        elif token == "drop":
            pop()
        elif token == "swap":
            b, a = pop(), pop()
            stack.append(b)
            stack.append(a)
        elif token == "over":
            if len(stack) < 2:
                raise StackUnderflowError("Insufficient number of items in stack")
            stack.append(stack[-2])
        else:
            raise ValueError("undefined operation")

    for line in input_data:
        tokens = line.lower().split()
        i = 0
        while i < len(tokens):
            if tokens[i] == ":":
                name = tokens[i + 1]
                if _NUMBER.fullmatch(name):
                    raise ValueError("illegal operation")
                end = tokens.index(";", i + 2)
                words[name] = tokens[i + 2 : end]
                i = end + 1
            else:
                execute(tokens[i])
                i += 1

    return stack

